  ["0198abafcd00877a"] = { "世界のどこで見つけようとも、彼らは何か大切なものを守っているのだと知っておくがいい。遠い昔にそう託されたのだから。", "." },
  ["019b2d4d090fa521"] = { "またtroggだ！爆薬の準備をする間、追い払ってくれ！", "." },
